def solve_part_one(lines):
    total = 0
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split(",")
        left = int(parts[0])
        right = int(parts[1])
        if left < right:
            total += right - left
        else:
            total += left - right
    return total


def solve_part_two(lines):
    counts = {}
    for line in lines:
        for word in line.split():
            word = word.strip(".,;:!?").lower()
            if not word:
                continue
            counts[word] = counts.get(word, 0) + 1
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:10]


class Grid:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.cells = [[0 for _ in range(cols)] for _ in range(rows)]

    def get(self, r, c):
        if r < 0 or r >= self.rows or c < 0 or c >= self.cols:
            return 0
        return self.cells[r][c]

    def set(self, r, c, value):
        if 0 <= r < self.rows and 0 <= c < self.cols:
            self.cells[r][c] = value

    def neighbours(self, r, c):
        out = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                out.append(self.get(r + dr, c + dc))
        return out

    def step(self, rule):
        nxt = Grid(self.rows, self.cols)
        for r in range(self.rows):
            for c in range(self.cols):
                live = sum(1 for n in self.neighbours(r, c) if n)
                nxt.set(r, c, rule(self.get(r, c), live))
        return nxt

    def render(self, on="#", off="."):
        lines = []
        for row in self.cells:
            lines.append("".join(on if cell else off for cell in row))
        return "\n".join(lines)


def parse_blocks(text):
    blocks = []
    current = []
    for line in text.splitlines():
        if line.strip() == "":
            if current:
                blocks.append(current)
                current = []
            continue
        current.append(line)
    if current:
        blocks.append(current)
    return blocks


def checksum(data, modulus=1000003):
    h = 0
    for byte in data:
        h = (h * 131 + byte) % modulus
    return h


def chunk(seq, size):
    for start in range(0, len(seq), size):
        yield seq[start:start + size]


def merge_sorted(a, b):
    out = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out


def flatten(tree):
    if isinstance(tree, dict):
        out = []
        for key in sorted(tree):
            out.append(key)
            out.extend(flatten(tree[key]))
        return out
    if isinstance(tree, (list, tuple)):
        out = []
        for item in tree:
            out.extend(flatten(item))
        return out
    return [tree]


def sliding_windows(values, width):
    out = []
    for i in range(len(values)):
        lo = max(0, i + 1 - width)
        out.append(sum(values[lo:i + 1]))
    return out
